export const button=(action,text,id='',className='secondary',extra='')=>`<button type="button" class="${className}" data-action="${action}" data-id="${e(id)}" ${extra}>${text}</button>`;
const heading=(title,action='')=>`<header class="r-heading"><h1>${title}</h1>${action}</header>`;
const empty=(text,action='')=>`<div class="r-empty"><p>${text}</p>${action}</div>`;
const paths={today:'M12 3a9 9 0 1 0 9 9M12 3v9l6 3',growth:'m4 18 5-7 4 3 7-10M15 4h5v5',plans:'M5 4h14v16H5zM8 8h8M8 12h5M8 16h8',memory:'M4 5h16v15H4zM8 5V3m8 2V3M8 10h8M8 14h5',iteration:'M5 8a8 8 0 0 1 13-2l2 2M20 3v5h-5M19 16a8 8 0 0 1-13 2l-2-2M4 21v-5h5',settings:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3'};
export const icon=k=>`<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]??paths.today}"/></svg>`;
export function shell(s,ui,content){const pages=[['today','记录'],['growth','成长'],['plans','阶段'],['memory','闪回'],['iteration','迭代'],['settings','个人']],selected=ui.navPage??ui.page;return `<div class="r-app"><aside class="r-sidebar"><div class="r-wordmark">NO GAME<br>NO LIFE<span>把日常，连成自己的轨迹。</span></div><nav class="r-nav" aria-label="主导航">${pages.map(([key,name])=>`<button type="button" data-nav="${key}" ${selected===key?'aria-current="page"':''}>${icon(key)}<span>${name}</span></button>`).join('')}</nav><small class="r-version">${APP_VERSION} · 本地记录</small></aside><main id="main" tabindex="-1" class="r-main">${Number.isInteger(ui.guideReturnStep)?button('guide-return','‹ 返回引导 · 第 '+(ui.guideReturnStep+1)+' 步','','text-button r-guide-return'):''}${ui.viewTrail?.length?button('page-back','‹ 返回','','text-button r-back'):''}${content}</main></div>`;}
export function today(s,ui){
 const r=s.running,today=D.dateKey(Date.now(),s.timeZone),stat=rangeStatistics(s,today,today),sleep=sleepRecords(s)[0],start=D.dayStart(today,s.timeZone),end=D.dayStart(D.addDays(today,1),s.timeZone),rows=stat.rows.filter(r=>!r.live),date=new Intl.DateTimeFormat('zh-CN',{timeZone:s.timeZone,month:'long',day:'numeric',weekday:'short'}).format(Date.now());
 return `<div class="r-record">${heading('记录',`<div class="r-heading-actions"><span class="r-date">${date}</span>${button('record-cover','封面','','text-button')}</div>`)}<div class="r-record-art" data-record-art ${resolveCover(s).mode==='hidden'?'hidden':''}><img src="${e(resolveCover(s).mode==='image'?(ui.assets??[]).find(a=>a.id===resolveCover(s).assetId)?.data??'./assets/art/time-poster-951e42dbc69a.png':'./assets/art/time-poster-951e42dbc69a.png')}" data-default-art="./assets/art/time-poster-951e42dbc69a.png" alt="" width="1742" height="903" decoding="async"></div><div data-record-message></div><div class="r-home-layout"><div><section class="r-timer ${r?'is-running':''}"><div class="r-record-clock"><div class="r-timer-label">${r?button('edit-current-name',e(r.temporaryName||r.name)+' <span aria-hidden="true">✎</span>','','text-button',`aria-label="编辑本次名称：${e(r.temporaryName||r.name)}"`):'<span>等待开始</span>'}</div><strong class="r-digits" data-live aria-live="off" aria-label="本次经过时间">00:00</strong>${r?.temporaryName?`<p class="r-timer-caption">${e(r.name)}</p>`:''}</div><div class="r-timer-actions">${button('choose-activity',r?'切换':'开始记录 <span aria-hidden="true">→</span>','','primary')}${r?button('stop','停止','','secondary'):''}</div></section><section class="r-section r-quick-section"><div class="r-quick-heading"><h2>快捷标签</h2></div><div class="r-quick-viewport"><div class="r-quick" id="quick-labels" data-quick-strip data-scroll-position role="group" aria-label="全部可启动固定标签，可横向滑动">${stableQuickLabels(s,ui.quickLabelOrder).map(a=>button('quick-start',`<i style="--label-color:${labelColor(s,a)}"></i><span>${e(a.name)}</span>`,a.id,'r-quick-item',r?.activityId===a.id?'aria-current="true"':'')).join('')}</div></div></section>${r?`<div class="r-footer-actions">${button('current-phone-mode',r.phoneMode==='focus'?'专注模式':'并行模式','','text-button')}${button('timer-reminder','结束提醒','','text-button')}</div>`:''}</div><section class="r-day-facts"><div class="section-title"><h2>今日时间</h2>${button('open-overview','时间概览 ↗','','text-button')}</div><div class="r-day-total"><strong>${durationParts(stat.confirmedMs/60000).map(p=>`<span class="r-duration-part"><span class="r-duration-value">${e(p.value)}</span><span class="r-duration-unit">${e(p.unit)}</span></span>`).join('')}</strong><small>已确认</small></div><div class="r-day-strip" role="img" aria-label="今天全天时间线，空白为未记录">${rows.map(v=>`<span style="background:${labelColor(s,v)};left:${(v.start-start)/(end-start)*100}%;width:${(v.end-v.start)/(end-start)*100}%" title="${e(v.name)} ${clock(v.start,s.timeZone)}—${clock(v.end,s.timeZone)}"></span>`).join('')}</div><div class="r-day-scale" aria-hidden="true"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div>${sleep&&sleep.date===today?`<p class="r-sleep">昨夜睡眠 ${duration(sleep.ms/60000)} · 入睡 ${clock(sleep.bedAt,s.timeZone)} / 起床 ${clock(sleep.wakeAt,s.timeZone)}</p>`:''}${rows.length?`<ol class="r-recent-time">${[...rows].sort((a,b)=>b.start-a.start).slice(0,3).map(v=>`<li><time>${clock(v.start,s.timeZone)}</time><strong>${e(v.temporaryName||v.name)}</strong><small>${duration((v.end-v.start)/60000)}</small></li>`).join('')}</ol>`:'<p class="quiet-note r-empty">记录一段以后，回看今天的经过。</p>'}</section></div>${!s.rebuild.guideDone?button('rebuild-guide','从第一条记录，了解应用 ›','','text-button r-guide-entry'):''}</div>`;
}
export function ring(rows,total,{small=false}={}){let offset=0;return `<svg class="r-ring ${small?'small':''}" viewBox="0 0 200 200" role="img" aria-label="已确认时间占比"><circle cx="100" cy="100" r="75" fill="none" stroke="var(--line)" stroke-width="22"/>${rows.map(row=>{const size=total?row.ms/total*100:0,part=`<circle cx="100" cy="100" r="75" pathLength="100" ${!small?`role="button" tabindex="0" data-action="select-trend" data-id="${e(row.id)}" data-group="${e(row.groupId)}" aria-label="${e(row.name)}时间线"`:""} fill="none" stroke="${row.color}" stroke-width="22" stroke-dasharray="${Math.max(0,size-.45)} ${100-Math.max(0,size-.45)}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"><title>${e(row.name)} ${duration(row.ms/60000)}</title></circle>`;offset+=size;return part;}).join('')}<text x="100" y="97" text-anchor="middle">${num(total/3600000)}</text><text class="r-ring-unit" x="100" y="119" text-anchor="middle">小时 · 已确认</text></svg>`;}
export function miniTime(s,date){const stat=rangeStatistics(s,date,date),rows=stat.rows.filter(r=>!r.live),start=D.dayStart(date,s.timeZone),end=D.dayStart(D.addDays(date,1),s.timeZone),span=end-start;return `<div class="r-time-mini">${ring(stat.labels,stat.confirmedMs,{small:true})}<div class="r-time-strip" role="img" aria-label="${date}全天时间线，空白为未记录" data-day-start="${start}" data-day-end="${end}">${rows.map(r=>`<span title="${e(r.name)} ${clock(r.start,s.timeZone)}—${clock(r.end,s.timeZone)}" data-start="${r.start}" data-end="${r.end}" style="background:${labelColor(s,r)};left:${(r.start-start)/span*100}%;width:${(r.end-r.start)/span*100}%"></span>`).join('')}</div><small><span class="r-time-mini-date">${date}</span><span class="r-time-mini-duration">${duration(stat.confirmedMs/60000)}</span></small></div>`;}

function trendChart(stat){
 const points=stat.trend,observed=points.filter(p=>p.status!=='future'),caption=p=>p.status==='future'?'未到':(p.status==='current'?'截至当前 · ':'')+(p.ms>0?duration(p.ms/60000):'无已确认记录'),values=`<div class="r-day-values">${points.map(p=>`<span data-date="${p.date}" data-status="${p.status}">${p.date}<b>${caption(p)}</b></span>`).join('')}</div>`;
 if(observed.length<2||!observed.some(p=>p.ms>0))return `<details class="r-trend-compact"><summary>${!observed.length?'所选日期尚未到来':observed.length===1?observed[0].date+' · '+caption(observed[0]):'该范围暂无已确认记录'} · 查看数值</summary>${values}</details>`;
 const max=Math.max(60000,...observed.map(p=>p.ms)),w=620,h=140,xy=points.flatMap((p,i)=>p.status==='future'?[]:[{p,x:28+(w-56)*i/(points.length-1),y:h-20-p.ms/max*(h-42)}]);
 return `<svg class="r-trend" viewBox="0 0 ${w} ${h}" role="img" aria-label="每日已确认时长趋势图，未来日期不绘制"><path d="M28 20V120H592" fill="none" stroke="var(--line)"/><polyline points="${xy.map(v=>v.x+','+v.y).join(' ')}" fill="none" stroke="var(--green)" stroke-width="2.5"/>${xy.map(({p,x,y})=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--green)" data-date="${p.date}"><title>${p.date} ${caption(p)}</title></circle>`).join('')}<text x="28" y="137">${points[0]?.date??''}</text><text x="592" y="137" text-anchor="end">${points.at(-1)?.date??''}</text></svg><details><summary>查看每日数值</summary>${values}</details>`;
}
export function overview(s,ui){const start=ui.statsStart??ui.date,end=ui.statsEnd??ui.date,stat=rangeStatistics(s,start,end,{groupId:ui.selectedGroup??null,activityId:ui.trendActivity??null,temporaryName:ui.trendTemporary??null}),selected=ui.selectedGroup,labels=stat.labels.filter(l=>!selected||l.groupId===selected),day=ui.date,dayStart=D.dayStart(day,s.timeZone),dayEnd=D.dayStart(D.addDays(day,1),s.timeZone),timeline=[...s.sessions,...(s.running?[{...s.running,end:Date.now(),live:true}]:[])].filter(r=>r.end>dayStart&&r.start<dayEnd&&inStatisticsScope(s,r,{groupId:selected,activityId:ui.trendActivity??null,temporaryName:ui.trendTemporary??null})).sort((a,b)=>b.start-a.start),ringRows=selected?labels:stat.labels;return `${heading('时间概览',button('phone-details','手机使用 ↗','','text-button'))}<div class="r-tabs">${[['day','日'],['week','周'],['month','月'],['custom','自选']].map(([id,title])=>button('range-mode',title,id,'text-button',`aria-pressed="${(ui.rangeMode??'day')===id}"`)).join('')}</div>${ui.rangeMode==='custom'?`<form id="r-range" class="r-range"><label>开始<input type="date" name="start" value="${start}" required></label><label>结束<input type="date" name="end" value="${end}" required></label><button class="secondary">查看</button></form>`:`<div class="r-period" id="r-period" data-start="${start}" data-end="${end}">${button('range-shift','‹','-1','secondary',`aria-label="上一${{day:'日',week:'周',month:'月'}[ui.rangeMode??'day']}"`)}<div><strong>${(ui.rangeMode??'day')==='month'?start.slice(0,7):start===end?start:start+' — '+end}</strong>${button('range-today','回到本'+({day:'日',week:'周',month:'月'}[ui.rangeMode??'day']),'','text-button')}</div>${button('range-shift','›','1','secondary',`aria-label="下一${{day:'日',week:'周',month:'月'}[ui.rangeMode??'day']}"`)}</div>`}<section class="r-stat-grid ${stat.confirmedMs?'':'r-stat-empty'}"><div>${stat.confirmedMs?ring(ringRows,selected?labels.reduce((n,r)=>n+r.ms,0):stat.confirmedMs):''}<p class="quiet-note">占比以${selected?'当前分类':'选定范围'}已确认主时间为分母${stat.liveMs?`；当前运行预览 ${duration(stat.liveMs/60000)}，不计入占比`:''}。</p></div><div class="r-group-list">${stat.groups.map(g=>`<details class="r-group" ${selected===g.id?'open':''}><summary>${button('select-group',`<i style="background:${g.color}"></i>${e(g.name)}`,g.id,'text-button')}<strong>${duration(g.ms/60000)}</strong><small>${num(g.percent)}%</small></summary>${stat.labels.filter(l=>l.groupId===g.id).map(l=>`<details class="r-label"><summary>${button('select-trend',e(l.name),l.id,'text-button',`data-group="${e(l.groupId)}"`)}<span>${duration(l.ms/60000)} · ${num(g.ms?l.ms/g.ms*100:0)}% · 分类内</span></summary>${stat.temporaries.filter(t=>t.activityId===l.id&&t.groupId===l.groupId).map(t=>button('select-temp',`${e(t.name)} <span>${duration(t.ms/60000)} · ${num(l.ms?t.ms/l.ms*100:0)}% · 标签内</span>`,l.id,'text-button',`data-name="${e(t.name)}" data-group="${e(t.groupId)}"`)).join('')||'<p class="quiet-note">本标签没有临时名称</p>'}</details>`).join('')}</details>`).join('')||empty('这个范围还没有确认记录。')}${selected||ui.trendActivity?button('clear-stat-filter','查看全部','','text-button'):''}</div></section><section class="r-section"><h2>${selected?e(stat.groups.find(g=>g.id===selected)?.name??'分类')+' / ':''}${ui.trendActivity?e(s.activities.find(a=>a.id===ui.trendActivity)?.name??'标签')+(ui.trendTemporary?' / '+e(ui.trendTemporary):''):selected?'分类合计':'全部主时间'} · 每日趋势</h2>${selected&&ui.trendActivity?button('label-all-groups','查看此标签的全部分类','','text-button'):''}${trendChart(stat)}</section><section class="r-section"><div class="r-heading"><h2>时间线</h2><input id="r-timeline-date" type="date" aria-label="时间线日期" value="${day}"></div><div class="r-inline">${button('add-session','＋ 补记','','text-button')}${button('organize-range','分段调整','','text-button')}${s.recordUndo?button('undo-time','撤销上次修改','','text-button'):''}</div><div class="r-timeline">${timeline.map(r=>`<button type="button" class="r-time-row" data-action="${r.live?'recovery':r.confirmation==='pending'?'organize-pending':'edit-time'}" data-id="${e(r.id)}" style="--label-color:${labelColor(s,r)}"><time>${clock(Math.max(dayStart,r.start),s.timeZone)}<small>${clock(Math.min(dayEnd,r.end),s.timeZone)}</small></time><span><strong>${e(r.name)}</strong>${r.temporaryName?`<small>${e(r.temporaryName)}</small>`:''}</span><b>${r.confirmation==='pending'?'待确认':r.live?'计时中':duration((Math.min(dayEnd,r.end)-Math.max(dayStart,r.start))/60000)}</b></button>`).join('')||empty('这一天自然留白。')}</div>${(ui.drafts??[]).filter(d=>['records','time-edit'].includes(d.kind)&&!d.payload.currentName).map(d=>button(d.kind==='time-edit'?'resume-time-edit':'resume-range','继续未完成的时间修改',d.kind==='time-edit'?(d.payload.original?.id??'new'):d.id,'text-button')).join('')}</section>`;}
export function plans(s,ui){const visible=s.phases.filter(p=>ui.archivedPhases?p.archived:!p.archived);return `${heading('阶段',button('new-phase','＋ 新阶段','','primary'))}<div class="r-stage-list">${visible.map(p=>{const tasks=s.plans.filter(t=>t.phaseId===p.id&&!t.archived),minutes=phaseSlices(s,p.id,D.confirmedSessions(s)).reduce((n,r)=>n+(r.end-r.start)/60000,0);return `<article class="r-stage"><button type="button" class="r-stage-title" data-action="phase-detail" data-id="${e(p.id)}"><span><small>${p.startDate} — ${p.endDate}</small><h2>${e(p.title)}</h2></span><b>↗</b></button><p>${tasks.length} 项任务 · 本期 ${duration(minutes)}</p>${tasks.slice(0,4).map(t=>button('task-detail',`${t.completedAt?'✓':'○'} ${e(t.title)}<small>${t.targetMinutes?duration(D.planProgress(s,t).minutes)+' / '+duration(t.targetMinutes):t.completedAt?'成果已确认':'成果待确认'}</small>`,t.id,'r-task-row')).join('')}${!tasks.length?'<p class="quiet-note">先定下阶段，再逐项加入任务。</p>':''}${button('new-task','＋ 添加任务',p.id,'text-button')}</article>`;}).join('')||empty(ui.archivedPhases?'还没有归档阶段。':'先为一段时间定下方向。')}${button('toggle-phase-archive',ui.archivedPhases?'回到进行中':'往期与归档','','text-button')}</div>${habits(s,ui)}<details class="r-section" id="phase-weekly-schedule" data-preserve><summary>每周安排</summary>${weeklyPlans(s,ui,{e,button:(a,t,c,id)=>button(a,t,id,c),embedded:true})}</details>`;}
export function phaseDetail(s,ui){const p=s.phases.find(p=>p.id===ui.phaseId);if(!p)return empty('阶段已不存在。');const tasks=s.plans.filter(t=>t.phaseId===p.id),rows=phaseSlices(s,p.id,D.confirmedSessions(s));return `${heading(e(p.title),button('edit-phase','编辑',p.id,'text-button'))}<p class="r-date">${p.startDate} — ${p.endDate}</p><div class="r-phase-summary"><strong>${duration(rows.reduce((n,r)=>n+(r.end-r.start)/60000,0))}</strong><span>阶段实录 · 多任务引用已去重</span></div>${p.note?`<p>${e(p.note)}</p>`:''}<section class="r-section"><div class="r-heading"><h2>任务框架</h2>${button('new-task','＋ 添加任务',p.id,'primary')}</div>${tasks.map(t=>button('task-detail',`${t.archived?'已归档 · ':''}${e(t.title)}<small>${t.targetMinutes?duration(D.planProgress(s,t).minutes)+' / '+duration(t.targetMinutes):''}${t.completedAt?' · 成果已确认':''}</small>`,t.id,'r-task-row')).join('')||empty('还没有任务。')}</section><section class="r-section"><h2>本期培养</h2>${s.skills.filter(k=>p.skillIds.includes(k.id)||rows.some(r=>r.mainSkillId===k.id||r.relatedSkillIds.includes(k.id))).map(k=>button('skill',`${e(k.name)}<span>${num(D.contribution(rows)[k.id]?.toNumber()??0)} 分</span>`,k.id,'r-task-row')).join('')||'<p class="quiet-note">阶段可选择培养方向，计时标签会带入真实贡献。</p>'}${button('phase-growth','期初与期内变化',p.id,'text-button')}</section>${button('archive-phase',p.archived?'恢复阶段':'归档阶段',p.id,'text-button')}`;}
export function taskDetail(s,ui){const t=s.plans.find(p=>p.id===ui.taskId);if(!t)return empty('任务已不存在。');const v=D.planProgress(s,t);return `${heading(e(t.title),button('edit-task','编辑',t.id,'text-button'))}<section class="r-section">${t.targetMinutes?`<div class="r-phase-summary"><strong>${duration(v.minutes)}</strong><span>目标 ${duration(t.targetMinutes)}</span></div>${bar(v.ratio)}`:''}${t.outcome?`<h2>成果</h2><p>${e(t.outcome)}</p>${button('complete-plan',t.completedAt?'查看已确认成果':'确认成果完成',t.id,'secondary')}`:''}</section><section class="r-section"><h2>固定计时标签</h2>${t.activityIds.map(id=>{const a=s.activities.find(a=>a.id===id);return button('quick-start',`${e(a?.name??id)} · 开始`,id,'secondary');}).join('')||'<p class="quiet-note">未关联固定标签。</p>'}${(t.groupIds?.length||t.skillIds.length)?'<p class="quiet-note">沿用旧计划的类别与主培养范围。</p>':''}<p class="quiet-note">时间与培养沿同一条记录；同一标签可能推进多个任务。</p></section>${button('archive-task',t.archived?'恢复任务':'归档任务',t.id,'text-button')}`;}
export function habits(s,ui){const day=D.dateKey(Date.now(),s.timeZone);return `<section class="r-section"><div class="r-heading"><h2>每日习惯</h2>${button('new-habit','＋ 新习惯','','text-button')}</div>${s.habits.filter(h=>ui.archivedHabits?h.archived:!h.archived).map(h=>{const v=habitSummary(s,h.id,D.dateKey(Date.now(),h.timeZone??s.timeZone));return `<div class="r-habit"><button type="button" class="r-check" data-action="check-habit" data-id="${e(h.id)}" data-date="${D.dateKey(Date.now(),h.timeZone??s.timeZone)}" data-checked="${!v.checked}" aria-label="${v.checked?'撤销':'完成'} ${e(h.title)}" aria-pressed="${v.checked}">${v.checked?'✓':'○'}</button>${button('habit-history',`${e(h.title)}<small>累计 ${v.total} 天 · 连续 ${v.current} 天</small>`,h.id,'r-habit-title')}</div>`;}).join('')||'<p class="quiet-note">轻轻勾选，留下一天的坚持。</p>'}${s.habits.some(h=>h.archived)?button('toggle-habit-archive',ui.archivedHabits?'返回日常':'归档习惯','','text-button'):''}</section>`;}
export function iteration(s,ui){const branch=ui.iterationBranch??'time',parent=ui.iterationParent??null,query=(ui.iterationQuery??'').trim().toLowerCase(),nodes=s.iterationNodes.filter(n=>n.branch===branch&&iterationArchived(s,n)===!!ui.iterationArchived&&(query?n.title.toLowerCase().includes(query)||iterationPath(s,n.id).toLowerCase().includes(query)||s.iterationEntries.some(v=>v.nodeId===n.id&&[...ITERATION_FIELDS.map(([k])=>v[k]),v.method].join(' ').toLowerCase().includes(query)):n.parentId===parent));return `${heading('迭代',button('new-iteration-node','＋ 新项目','','primary'))}<div class="r-segmented" role="group" aria-label="迭代模式">${button('iteration-branch','日常优化','time','text-button',`aria-pressed="${branch==='time'}"`)}${button('iteration-branch','事项复盘','event','text-button',`aria-pressed="${branch==='event'}"`)}</div><form id="r-iteration-search" class="r-search"><input name="query" type="search" aria-label="搜索项目" placeholder="搜索项目或路径" value="${e(query)}"><button class="text-button">搜索</button></form>${parent?`<div class="r-breadcrumb">${button('iteration-up','‹ 上一级','','text-button')}<span>${e(iterationPath(s,parent))}</span>${button('new-iteration-entry','记一次',parent,'primary')}</div>`:''}<div class="r-project-list">${nodes.map(n=>`<article class="r-project"><button type="button" class="r-project-title" data-action="iteration-project" data-id="${e(n.id)}"><small>${n.kind==='category'?'分类':query?e(iterationPath(s,n.id)):'项目'}</small><h2>${e(n.title)}</h2><span>${s.iterationEntries.filter(v=>v.nodeId===n.id).length} 次记录 · ${s.iterationNodes.filter(v=>v.parentId===n.id&&!v.archived).length} 子项</span></button>${button('new-iteration-entry','记一次',n.id,'text-button')}</article>`).join('')||(query?empty('没有找到项目。'):parent?'':empty(ui.iterationArchived?'暂无归档项目。':'直接建一个项目，就可以开始记录。'))}</div>${parent?iterationEntries(s,parent,ui):''}<div class="r-inline">${button('toggle-iteration-archive',ui.iterationArchived?'查看进行中':'查看归档','','text-button')}${parent?button('edit-iteration-node','项目设置',parent,'text-button'):''}</div><details class="r-section"><summary>既有每周复看与个人表现</summary>${weeklyInsights(s,ui,{e,button:(a,t,c,id)=>button(a,t,id,c),duration,num})}</details>`;}
function iterationEntries(s,nodeId,ui){
 const rows=s.iterationEntries.filter(v=>v.nodeId===nodeId&&(!ui.iterationDate||D.dateKey(v.at,s.timeZone)===ui.iterationDate)).sort((a,b)=>b.at-a.at);
 return `<section class="r-section"><div class="r-heading"><h2>每次记录</h2><input id="r-iteration-date" type="date" aria-label="按日期回看" value="${ui.iterationDate??''}"></div><form id="r-compare"><div class="r-entry-list">${rows.map(v=>`<article class="r-iteration-entry"><header><h3>第 ${iterationNumber(s,v)} 次记录</h3>${button('edit-iteration-entry','编辑',v.id,'text-button')}</header><p class="r-entry-excerpt">${e(ITERATION_FIELDS.map(([k])=>v[k]).find(Boolean)||v.method||'')}</p><div class="r-entry-meta"><time>${D.dateKey(v.at,s.timeZone)}</time>${v.reference?'<span class="tag">个人参考</span>':''}<label class="check"><input type="checkbox" name="entries" value="${e(v.id)}" aria-label="比较第 ${iterationNumber(s,v)} 次记录">加入比较</label></div></article>`).join('')||empty('只写一项也可以。')}</div>${rows.length>1?'<button class="secondary">并排比较所选记录</button>':''}</form></section>`;
}

export function memory(s,ui){
 const kind=ui.memoryKind??'daily',query=(ui.memoryQuery??'').toLowerCase(),all=diaryEntries(s).filter(m=>(m.entryKind??'daily')===kind);
 const rows=all.filter(m=>(!query||(m.title+' '+m.text+' '+(m.attachments??[]).map(f=>f.name).join(' ')).toLowerCase().includes(query)));
 return `${heading('闪回',`<div class="r-heading-actions">${button(kind==='daily'?'new-moment':'new-note',kind==='daily'?'＋ 写闪回':'＋ 写碎念','','primary')}${button('memory-search-toggle','<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg>','','text-button r-search-toggle',`aria-label="${ui.memorySearchOpen?'收起':'展开'}闪回搜索" aria-expanded="${!!ui.memorySearchOpen}" aria-controls="r-memory-search"`)}</div>`)}
 <div class="r-segmented" role="group" aria-label="闪回模式">${button('memory-kind','每日闪回','daily','text-button',`aria-pressed="${kind==='daily'}"`)}${button('memory-kind','碎念','note','text-button',`aria-pressed="${kind==='note'}"`)}</div>
 ${ui.memorySearchOpen?`<form id="r-memory-search" class="r-search"><input name="query" type="search" aria-label="搜索闪回" placeholder="寻找一个词、一段记忆" value="${e(ui.memorySearchDraft??ui.memoryQuery??'')}"><button class="text-button">搜索</button></form>`:''}
 ${query?`<p class="r-search-filter" role="status">正在筛选：${e(ui.memoryQuery)} ${button('memory-search-clear','清除','','text-button')}</p>`:''}
 <div class="r-calendar-toolbar"><span class="quiet-note">${rows.length} 条</span>${button('memory-calendar-toggle','<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16M8 15h2m4 0h2M8 18h2"/></svg>','','text-button r-calendar-trigger',`aria-label="按年月定位" aria-controls="memory-calendar" aria-expanded="false" ${rows.length?'':'disabled'}`)}</div>
 <aside id="memory-calendar" class="r-calendar-panel" aria-label="按年月定位" role="dialog" hidden><header><strong>年月定位</strong>${button('memory-calendar-close','×','','text-button',`aria-label="关闭年月索引"`)}</header><div class="r-calendar-scroll" tabindex="-1">${[...new Set(rows.map(m=>D.dateKey(m.at,s.timeZone).slice(0,4)))].map(year=>`<section><h3>${year} 年</h3>${[...new Set(rows.map(m=>D.dateKey(m.at,s.timeZone).slice(0,7)))].filter(m=>m.startsWith(year)).map(month=>button('memory-month',Number(month.slice(5))+' 月',month,'text-button',`aria-label="定位到 ${month.slice(0,4)} 年 ${Number(month.slice(5))} 月" aria-current="${ui.memoryMonth===month}"`)).join('')}</section>`).join('')}</div></aside>
 ${(ui.drafts??[]).filter(d=>d.kind==='diary'&&(d.entryKind??'daily')===kind).map(d=>button('resume-diary','继续写：'+e(d.title||d.text?.slice(0,24)||'未命名'),d.id,'r-draft-link')).join('')}
 <div class="r-memory-list">${rows.map(m=>`<article class="r-memory-entry" data-memory-month="${D.dateKey(m.at,s.timeZone).slice(0,7)}" tabindex="-1"><button type="button" class="r-memory-open" data-action="moment" data-id="${e(m.id)}"><div class="r-memory-copy"><h2>${e(m.title||'无题')}</h2>${m.text?`<p>${e(m.text.slice(0,200))}${m.text.length>200?'…':''}</p>`:''}<div class="r-entry-meta"><time>${D.dateKey(m.at,s.timeZone)}</time>${m.attachments?.length?`<span>▱ ${m.attachments.length} 个文件</span>`:''}</div></div>${m.photos.length?`<img class="r-memory-thumb" src="${e(m.photos[0].data)}" alt="${e(m.photos[0].name)}" loading="lazy">`:''}</button></article>`).join('')||empty(query?'没有找到对应内容。':'有想留下的，就写在这里。')}</div>`;
}

export function settings(s,ui){return `${heading('个人')}<div class="r-personal-list"><section><h2>你的应用</h2>${button('appearance','外观、背景与寄语 ↗','','r-personal-row')}${button('manage-activities','分类与固定标签 ↗','','r-personal-row')}${button('open-relations','关联图 ↗','','r-personal-row')}${button('rebuild-guide','分步引导 · 继续或重看 ↗','','r-personal-row')}${button('toggle-diary-time',`每日闪回附入时间摘要 <span>${s.rebuild.includeDiaryTime?'开启':'关闭'}</span>`,'','r-personal-row')}${button('toggle-motion',`减少动态效果 <span>${s.settings.reducedMotion?'开启':'跟随系统'}</span>`,'','r-personal-row')}</section><details id="settings-phone" data-preserve><summary>通知、浮球与手机记录</summary>${phoneSettings(s,ui,{e,duration,clock})}<section class="r-section"><h3>离开应用时的计时浮球</h3>${ui.native?`<p>${ui.nativeStatus?.overlayAllowed?'系统已允许悬浮显示':'需你授予“显示在其他应用上层”权限'} · ${ui.nativeStatus?.overlayEnabled?'已启用':'未启用'}</p>${ui.nativeStatus?.overlayError?'<p class="form-error">'+e(ui.nativeStatus.overlayError)+'</p>':''}${button('overlay-settings','打开系统悬浮权限','','secondary')}${button('toggle-overlay',ui.nativeStatus?.overlayEnabled?'关闭浮球':'启用浮球','','secondary')}`:'<p>浮球与锁屏通知在 Android 安装包内使用。</p>'}<p class="quiet-note">离开应用显示，回来收起。拒绝悬浮权限仍可记录并使用系统通知。</p></section></details>${(ui.drafts??[]).filter(d=>d.kind!=='diary').length?`<details id="resume-drafts" data-preserve><summary>未完成的编辑</summary>${ui.drafts.filter(d=>d.kind!=='diary').map(d=>button('resume-any-draft',e(d.payload?.values?.title??d.payload?.values?.name??({records:'时间调整',plan:'原阶段编辑',activity:'标签设置',appearance:'外观设置',setup:'原初始化设置'}[d.kind]??'继续编辑')),d.id,'r-personal-row')).join('')}</details>`:''}<details id="backup-section" data-preserve><summary>完整备份与恢复</summary><p>含记录、培养、阶段、习惯、闪回图片与文件、迭代、手机记录、草稿和背景。</p><div class="r-inline">${button('backup','导出完整备份','','primary')}<label class="secondary file-button">导入备份<input id="import-backup" type="file" accept=".json,application/json" hidden></label>${button('restore-point','恢复替换前的数据','','text-button')}${button('export-original','导出升级前备份','','text-button')}</div></details><details id="settings-device" data-preserve><summary>设备与数据</summary><dl class="info-list"><div><dt>版本</dt><dd>${APP_VERSION}</dd></div><div><dt>日期口径</dt><dd>${e(s.timeZone)}</dd></div><div><dt>保存</dt><dd id="storage-status">本机</dd></div><div><dt>离线</dt><dd id="offline-status"></dd></div></dl>${button('export-range','按日期导出文字','','text-button')}${button('reset','清空当前数据','','text-button')}</details></div>`;}
export function phone(s,ui){return heading('手机使用')+phoneCard(s,{e,duration,clock,date:ui.date},false);}
export const pages={today,overview,plans,phaseDetail,taskDetail,memory,iteration,settings,phone,growth,skillDetail,stageOverview};
